// AUTHENTICATION & USER PROFILE CONTROLLER (OPEN ACCESS)
// ============================================================

let _inflightWhitelistPromises = new Map();

function getCachedWhitelistEntry(email) {
  try {
    const raw = localStorage.getItem('slant_whitelist_cache_v2');
    if (!raw) return null;
    const map = JSON.parse(raw);
    const entry = map && map[email];
    // Cache allowed status for up to 24 hours for instant 0ms login boot
    if (entry && entry.allowed && (Date.now() - (entry.ts || 0) < 86400000)) {
      return entry;
    }
  } catch (_) {}
  return null;
}

function setCachedWhitelistEntry(email, result) {
  try {
    if (!email || !result || !result.allowed) return;
    const raw = localStorage.getItem('slant_whitelist_cache_v2');
    const map = raw ? JSON.parse(raw) : {};
    map[email] = {
      allowed: Boolean(result.allowed),
      isAdmin: Boolean(result.isAdmin),
      credits: result.credits || null,
      ts: Date.now()
    };
    localStorage.setItem('slant_whitelist_cache_v2', JSON.stringify(map));
  } catch (_) {}
}

async function fetchWhitelistFromNetwork(email) {
  if (_inflightWhitelistPromises.has(email)) {
    return _inflightWhitelistPromises.get(email);
  }
  const promise = (async () => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3500);
      const resp = await fetch(`/api/whitelist?email=${encodeURIComponent(email)}`, {
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      if (resp.ok) {
        const data = await resp.json();
        if (data.credits) {
          updateCreatorStudioCreditBadge(data.credits);
        }
        const res = { allowed: Boolean(data.allowed), isAdmin: Boolean(data.isAdmin), credits: data.credits || null };
        if (res.allowed) setCachedWhitelistEntry(email, res);
        return res;
      }
    } catch (err) {
      console.warn('Whitelist API check notice, falling back to direct Supabase:', err);
    }

    // Resilient fallback: direct Supabase point lookup
    try {
      const supaResp = await fetch(`${SUPABASE_URL}/rest/v1/posts?id=eq.system_beta_whitelist&select=data`, {
        headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}` }
      });
      if (supaResp.ok) {
        const rows = await supaResp.json();
        const list = rows?.[0]?.data?.allowed_emails || [];
        const admins = rows?.[0]?.data?.admin_emails || [];
        const isAllowed = list.map(e => String(e).toLowerCase().trim()).includes(email) || admins.map(e => String(e).toLowerCase().trim()).includes(email);
        const isAdmin = admins.map(e => String(e).toLowerCase().trim()).includes(email);
        const res = { allowed: isAllowed, isAdmin };
        if (res.allowed) setCachedWhitelistEntry(email, res);
        return res;
      }
    } catch (_) {}

    const isMaster = email === 'shridharoct16@gmail.com' || email === 'basasridhara@gmail.com';
    return { allowed: isMaster, isAdmin: isMaster };
  })();

  _inflightWhitelistPromises.set(email, promise);
  try {
    return await promise;
  } finally {
    _inflightWhitelistPromises.delete(email);
  }
}

async function verifyUserWhitelist(user) {
  if (!user || !user.email) return { allowed: false, isAdmin: false };
  const email = user.email.toLowerCase().trim();

  // 1. Instant 0ms fast-track for Master Admin
  if (email === 'shridharoct16@gmail.com' || email === 'basasridhara@gmail.com') {
    updateCreatorStudioCreditBadge({ isUnlimited: true, usedToday: 0, remainingToday: 9999, perspectiveRemainingToday: 9999, chronicleRemainingToday: 9999 });
    fetchWhitelistFromNetwork(email).catch(() => {});
    return { allowed: true, isAdmin: true };
  }

  // 2. Instant 0ms fast-track for previously verified whitelisted curators (refreshing credits in background)
  const cached = getCachedWhitelistEntry(email);
  if (cached && cached.allowed) {
    if (cached.credits) updateCreatorStudioCreditBadge(cached.credits);
    fetchWhitelistFromNetwork(email).catch(() => {});
    return { allowed: true, isAdmin: Boolean(cached.isAdmin), credits: cached.credits || null };
  }

  // 3. First-time sign-in check with deduplicated network lookup
  return fetchWhitelistFromNetwork(email);
}

let suppressSignOutNotice = false;
let isUninvitedGateActive = false;

async function handleUninvitedUser(user) {
  if (!user) return;
  const uninvitedEmail = (user.email || '').toLowerCase().trim();
  const uninvitedName = getUserDisplayName(user);
  const uninvitedAvatar = getUserAvatarUrl(user);

  isUninvitedGateActive = true;
  try {
    sessionStorage.setItem('slant_gate_active_email', uninvitedEmail);
  } catch (_) {}

  // 1. Immediately dismiss any full-screen loading video / splash overlay
  if (typeof dismissInitialFeedLoader === 'function') {
    dismissInitialFeedLoader(true);
  }

  // 2. Submit access request to server
  try {
    fetch('/api/whitelist', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'request_access',
        email: uninvitedEmail,
        name: uninvitedName,
        avatar: uninvitedAvatar
      })
    });
  } catch (_) {}

  // 3. Clear URL hash so checkDeepLink doesn't trigger auth modal
  try {
    if (window.location.hash) {
      history.replaceState(null, '', window.location.pathname);
    }
  } catch (_) {}

  // 4. Prevent confusing "Signed out successfully" toast from overwriting gate message
  suppressSignOutNotice = true;
  try {
    await supabaseClient.auth.signOut();
  } catch (_) {}

  currentUser = null;
  isCurrentUserAdmin = false;
  isUserWhitelistAllowed = false;

  closeAuthModal();
  updateAuthUI();

  // 5. Open the locked Private Preview Gate modal with requester's email (z-index 10000000)
  openPrivatePreviewGateModal(uninvitedEmail);
  setTimeout(() => {
    openPrivatePreviewGateModal(uninvitedEmail);
  }, 120);

  showTemporaryToast(`🔒 Access Restricted: ${uninvitedEmail} is not on the invited curator list.`, 6000);
}

async function initAuth() {
  if (!supabaseClient) {
    updateAuthUI();
    return;
  }

  try {
    const { data: { session } } = await supabaseClient.auth.getSession();
    if (session?.user) {
      const check = await verifyUserWhitelist(session.user);
      if (check.allowed) {
        currentUser = session.user;
        isCurrentUserAdmin = check.isAdmin;
        isUserWhitelistAllowed = true;
        try {
          if (currentUser.email) {
            localStorage.setItem('slant_user_email', currentUser.email.toLowerCase().trim());
          }
        } catch (_) {}
        if (currentUser?.user_metadata) {
          const cloudDeleted = currentUser.user_metadata.deleted_posts;
          if (Array.isArray(cloudDeleted) && cloudDeleted.length > 0) {
            applyDeletedPostsTombstone(cloudDeleted);
          }
          const cloudSaved = currentUser.user_metadata.saved_posts;
          if (Array.isArray(cloudSaved) && cloudSaved.length > 0) {
            cloudSaved.forEach(id => { if (!deletedPostIds.has(id)) savedPostIds.add(id); });
            localStorage.setItem('slant_saved_posts', JSON.stringify(Array.from(savedPostIds)));
          }
          const cloudMy = currentUser.user_metadata.my_posts;
          if (Array.isArray(cloudMy) && cloudMy.length > 0) {
            cloudMy.forEach(id => { if (!deletedPostIds.has(id)) myCreatedPostIds.add(id); });
            localStorage.setItem('slant_my_posts', JSON.stringify(Array.from(myCreatedPostIds)));
          }
        }
        sanitizeUserOwnershipAndCache();
        closeAuthModal();
        checkPendingSharedDataOnAuth();
        loadFamilyCastProfile(true);
        fetchAuthorStoriesFromCloud();
      } else {
        await handleUninvitedUser(session.user);
        return;
      }
    } else {
      currentUser = null;
      isCurrentUserAdmin = false;
      isUserWhitelistAllowed = false;
      try { localStorage.removeItem('slant_user_email'); } catch (_) {}
      sanitizeUserOwnershipAndCache();
    }
    updateAuthUI();
    if (isCurrentUserAdmin) {
      loadAdminBetaPendingCount();
    }
  } catch (err) {
    console.warn('Error fetching initial session:', err);
  }

  supabaseClient.auth.onAuthStateChange(async (event, session) => {
    if (event === 'SIGNED_IN') {
      if (session?.user) {
        // Avoid duplicate verification & duplicate post fetches if initAuth() already processed this user on boot
        const alreadyBootedSameUser = Boolean(currentUser && isUserWhitelistAllowed && currentUser.id === session.user.id);
        const check = alreadyBootedSameUser
          ? { allowed: true, isAdmin: isCurrentUserAdmin }
          : await verifyUserWhitelist(session.user);
        if (check.allowed) {
          currentUser = session.user;
          isCurrentUserAdmin = check.isAdmin;
          isUserWhitelistAllowed = true;
          try {
            if (currentUser.email) {
              localStorage.setItem('slant_user_email', currentUser.email.toLowerCase().trim());
            }
          } catch (_) {}
          closeAuthModal();
          checkPendingSharedDataOnAuth();
          if (!alreadyBootedSameUser) {
            loadFamilyCastProfile(true);
            showTemporaryToast(`Welcome to Slant, ${escapeHtml(getUserDisplayName())}! ✨`);
          }

          // Log access timestamp asynchronously
          try {
            fetch('/api/whitelist', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                action: 'log_access',
                email: session.user.email,
                name: getUserDisplayName(),
                avatar: getUserAvatarUrl()
              })
            });
          } catch (_) {}

          // Restore cloud-saved bookmarks, authored stories, and deleted tombstones from user metadata
          if (currentUser?.user_metadata) {
            const cloudDeleted = currentUser.user_metadata.deleted_posts;
            if (Array.isArray(cloudDeleted) && cloudDeleted.length > 0) {
              applyDeletedPostsTombstone(cloudDeleted);
            }
            const cloudSaved = currentUser.user_metadata.saved_posts;
            if (Array.isArray(cloudSaved) && cloudSaved.length > 0) {
              cloudSaved.forEach(id => { if (!deletedPostIds.has(id)) savedPostIds.add(id); });
              localStorage.setItem('slant_saved_posts', JSON.stringify(Array.from(savedPostIds)));
            }
            const cloudMy = currentUser.user_metadata.my_posts;
            if (Array.isArray(cloudMy) && cloudMy.length > 0) {
              cloudMy.forEach(id => { if (!deletedPostIds.has(id)) myCreatedPostIds.add(id); });
              localStorage.setItem('slant_my_posts', JSON.stringify(Array.from(myCreatedPostIds)));
            }
          }

          sanitizeUserOwnershipAndCache();

          if (isDeepLinkScrollGated) {
            isDeepLinkScrollGated = false;
            const gate = document.getElementById('deepLinkFeedGate');
            if (gate) gate.remove();
          }

          const redirectCurator = sessionStorage.getItem('slant_redirect_curator');
          if (redirectCurator) {
            sessionStorage.removeItem('slant_redirect_curator');
            setTimeout(() => filterByCurator(redirectCurator), 500);
          }

          let returnUrl = sessionStorage.getItem('slant_auth_redirect_url');
          if (returnUrl) {
            sessionStorage.removeItem('slant_auth_redirect_url');
            returnUrl = returnUrl
              .replace(/#login.*$/, '')
              .replace(/([?&])(auth=login|login=true)(&|$)/, '$1')
              .replace(/[?&]$/, '');
            try {
              if (returnUrl && window.location.href !== returnUrl && !returnUrl.endsWith('#login')) {
                history.replaceState(null, '', returnUrl);
              } else if (window.location.hash === '#login') {
                const cleanUrl = window.location.pathname + window.location.search;
                history.replaceState(null, '', cleanUrl);
              }
            } catch (_) {}
          } else if (window.location.hash === '#login') {
            try {
              const cleanUrl = window.location.pathname + window.location.search;
              history.replaceState(null, '', cleanUrl);
            } catch (_) {}
          }

          if (!alreadyBootedSameUser) {
            checkLiveSupabaseUpdates(true);
            fetchAuthorStoriesFromCloud();
          }
          updateAuthUI();
          if (isCurrentUserAdmin) {
            loadAdminBetaPendingCount();
          }
        } else {
          await handleUninvitedUser(session.user);
        }
      }
    } else if (event === 'SIGNED_OUT') {
      currentUser = null;
      isCurrentUserAdmin = false;
      isUserWhitelistAllowed = false;
      familyCastProfileCache = null;
      activeVaultMemberId = null;
      if (typeof activeCastMemberIds !== 'undefined' && activeCastMemberIds instanceof Set) {
        activeCastMemberIds.clear();
      }
      try {
        localStorage.removeItem('slant_user_email');
        localStorage.removeItem('slant_my_posts');
        localStorage.removeItem('slant_user_posts_cache');
        localStorage.removeItem('slant_family_cast');
        localStorage.removeItem('slant_form_drafts');
        localStorage.removeItem('slant_last_active_form_draft_id');
        localStorage.removeItem('slant_polish_history_v1');
        localStorage.removeItem('slant_reflection_feedback_history');
      } catch (_) {}
      myCreatedPostIds.clear();
      sanitizeUserOwnershipAndCache();
      const deepPostId = typeof getDeepLinkedPostId === 'function' ? getDeepLinkedPostId() : null;
      if (deepPostId) {
        isDeepLinkScrollGated = true;
        if (typeof setupDeepLinkScrollGate === 'function') {
          setupDeepLinkScrollGate();
        }
      }
      closeAuthModal();
      updateAuthUI();
      if (!suppressSignOutNotice) {
        showTemporaryToast('Signed out successfully.');
      }
      suppressSignOutNotice = false;
      if (currentFilter === 'my_stories' || currentFilter === 'daily_chronicles' || currentFilter === 'diary' || currentFilter === 'drafts') {
        selectCategory('all');
      } else {
        renderFeed();
      }
    }
  });
}

function syncUserMetadataToCloud() {
  if (currentUser && supabaseClient && typeof supabaseClient.auth?.updateUser === 'function') {
    try {
      supabaseClient.auth.updateUser({
        data: {
          saved_posts: Array.from(savedPostIds),
          my_posts: Array.from(myCreatedPostIds),
          deleted_posts: Array.from(deletedPostIds)
        }
      }).catch(err => console.warn('Could not sync user metadata:', err));
    } catch (e) {}
  }
}

function getUserDisplayName() {
  if (!currentUser) return 'Reader';
  const meta = currentUser.user_metadata || {};
  return meta.full_name || meta.name || currentUser.email?.split('@')[0] || 'Reader';
}

function getUserAvatarUrl() {
  if (!currentUser) return null;
  const meta = currentUser.user_metadata || {};
  return meta.avatar_url || meta.picture || null;
}

function getResolvedCreatorEmail() {
  if (currentUser?.email) return currentUser.email.trim().toLowerCase();
  return '';
}

function isPostChronicleDiary(post) {
  if (!post) return false;
  return Boolean(
    post.chronicleMode
    || post.innerVoiceSubMode === 'chronicle'
    || post.isDiary
    || post.isEncryptedDiary
    || post.encryptedDiaryPayload
    || post.generationInputs?.chronicleMode
    || (Array.isArray(post.chronicleMoments) && post.chronicleMoments.length > 0)
    || (Array.isArray(post.generationInputs?.chronicleMoments) && post.generationInputs.chronicleMoments.length > 0)
    || /(?:\b01\s*[·•.-]\s*[^:]{1,38}:|\bMoment\s+0?1\s*:)/i.test(String(post.summary || post.broadsheetObservation || ''))
  );
}

function isPostPrivateOrDraft(post) {
  if (!post) return false;
  if (isPostChronicleDiary(post)) {
    return true;
  }
  return Boolean(post.isDraft === true || post.isPrivate === true || post.status === 'draft');
}

const LOGIN_SHOWCASE_ONLY_POST_IDS = new Set([
  'slant-1792357651142-l7z3b',
  'slant-1792397027404-7rawu',
  'slant-1793003556503-aa54x-showcase',
  'slant-1793031039451-4bovq-showcase',
  'slant-1792429695314-6thox',
  'slant-1792437452220-xd5vt'
]);

function isLoginShowcaseOnlyPost(postOrId) {
  const id = typeof postOrId === 'string' ? postOrId : postOrId?.id;
  if (!id) return false;
  if (LOGIN_SHOWCASE_ONLY_POST_IDS.has(id)) return true;
  if (typeof postOrId === 'object' && postOrId?.isLoginFeatured) return true;
  return false;
}

function isPostOwnedByCurrentUser(post) {
  if (!post || isLoginShowcaseOnlyPost(post)) return false;
  const userEmail = (currentUser?.email || '').trim().toLowerCase();
  if (!currentUser || !userEmail) return false;

  const isShridharUser = (userEmail === 'shridharoct16@gmail.com' || userEmail === 'basasridhara@gmail.com');
  const postEmail = (post.userEmail || post.creatorEmail || '').trim().toLowerCase();
  const postAuthor = (post.creatorHandle || '').trim().toLowerCase().replace(/^@/, '');
  const isPostShridhar = (
    postEmail === 'shridharoct16@gmail.com'
    || postEmail === 'basasridhara@gmail.com'
    || (!postEmail && (postAuthor === 'shridhar reddy' || postAuthor.includes('shridhar')))
  );

  // 1. If the post has an explicit author email stamped on it, enforce strict email equality
  // (never allow polluted myCreatedPostIds or display name collisions to override userEmail!)
  if (postEmail) {
    if (isShridharUser && (postEmail === 'shridharoct16@gmail.com' || postEmail === 'basasridhara@gmail.com')) {
      return true;
    }
    return postEmail === userEmail;
  }

  // 2. For private Daily Chronicles / Diary entries without postEmail, ONLY allow legacy Shridhar entries when Shridhar is signed in
  if (isPostChronicleDiary(post)) {
    return Boolean(isShridharUser && isPostShridhar);
  }

  // 3. Never allow a non-Shridhar user to claim a @Shridhar Reddy post via polluted localStorage
  if (isPostShridhar && !isShridharUser) {
    return false;
  }

  const userHandle = (currentUser?.user_metadata?.user_name || currentUser?.user_metadata?.name || userEmail.split('@')[0] || '').toLowerCase().replace(/^@/, '');
  const postUserId = post.user_id || post.userId;

  return Boolean(
    (currentUser?.id && postUserId && postUserId === currentUser.id) ||
    (userHandle && postAuthor && postAuthor === userHandle) ||
    (isShridharUser && isPostShridhar) ||
    myCreatedPostIds.has(post.id)
  );
}

// Known Shridhar-authored diary IDs so they are immediately purged if they ever leaked into another user's localStorage/metadata
const SHRIDHAR_PRIVATE_DIARY_IDS = new Set([
  'slant-1793286852693-ktwwn',
  'slant-1793202119311-npt7z',
  'slant-1793149246670-6xt7k',
  'slant-1793031039451-4bovq',
  'slant-1793003556503-aa54x'
]);

function sanitizeUserOwnershipAndCache() {
  const userEmail = (currentUser?.email || '').trim().toLowerCase();
  const isShridharUser = (userEmail === 'shridharoct16@gmail.com' || userEmail === 'basasridhara@gmail.com');

  // Always purge legacy un-scoped family cast key so no user ever inherits another user's cached vault
  try {
    localStorage.removeItem('slant_family_cast');
  } catch (_) {}

  // If the signed-in user changed since last session, reset local my_posts, family vault cache, and form drafts
  try {
    const prevEmail = (localStorage.getItem('slant_last_auth_owner_email') || '').trim().toLowerCase();
    if (userEmail && prevEmail && prevEmail !== userEmail) {
      myCreatedPostIds.clear();
      familyCastProfileCache = null;
      activeVaultMemberId = null;
      if (typeof activeCastMemberIds !== 'undefined' && activeCastMemberIds instanceof Set) {
        activeCastMemberIds.clear();
      }
      localStorage.removeItem('slant_my_posts');
      localStorage.removeItem('slant_user_posts_cache');
      localStorage.removeItem('slant_form_drafts');
      localStorage.removeItem('slant_last_active_form_draft_id');
      localStorage.removeItem('slant_polish_history_v1');
      localStorage.removeItem('slant_reflection_feedback_history');
    }
    if (userEmail) {
      localStorage.setItem('slant_last_auth_owner_email', userEmail);
    }
  } catch (_) {}

  let myIdsModified = false;
  if (!isShridharUser) {
    for (const sid of SHRIDHAR_PRIVATE_DIARY_IDS) {
      if (myCreatedPostIds.has(sid)) {
        myCreatedPostIds.delete(sid);
        myIdsModified = true;
      }
    }
  }

  // Purge any foreign posts from slant_user_posts_cache
  try {
    const rawCache = localStorage.getItem('slant_user_posts_cache');
    if (rawCache) {
      const parsedCache = JSON.parse(rawCache);
      if (Array.isArray(parsedCache)) {
        const cleanCache = parsedCache.filter(p => {
      if (!p || !p.id) return false;
      if (!currentUser) return !isPostPrivateOrDraft(p);
      const owned = isPostOwnedByCurrentUser(p);
      if (!owned && myCreatedPostIds.has(p.id)) {
        myCreatedPostIds.delete(p.id);
        myIdsModified = true;
      }
      if (isPostPrivateOrDraft(p) && !owned) return false;
      return owned;
    });
    if (cleanCache.length !== parsedCache.length) {
      localStorage.setItem('slant_user_posts_cache', JSON.stringify(cleanCache));
    }
  }
}
} catch (_) {}

// Purge any foreign diary or draft posts from in-memory allPosts and purge non-owned IDs from myCreatedPostIds
if (Array.isArray(allPosts) && allPosts.length > 0) {
allPosts = allPosts.filter(p => {
  if (!p) return false;
  const owned = isPostOwnedByCurrentUser(p);
  if (!owned && p.id && myCreatedPostIds.has(p.id)) {
    myCreatedPostIds.delete(p.id);
    myIdsModified = true;
  }
  if (isPostPrivateOrDraft(p) && !owned) {
    return false;
  }
  return true;
});
}

  if (myIdsModified) {
    try {
      localStorage.setItem('slant_my_posts', JSON.stringify(Array.from(myCreatedPostIds)));
    } catch (_) {}
    if (currentUser) {
      syncUserMetadataToCloud();
    }
  }
}

function updateAuthUI() {
  const signedInView = document.getElementById('signedInAppView');
  const signedOutView = document.getElementById('signedOutPageView');
  const deepPostId = typeof getDeepLinkedPostId === 'function' ? getDeepLinkedPostId() : null;

  const signInBtn = document.getElementById('headerAuthBtn');
  const userMenuWrap = document.getElementById('userMenuWrap');
  const userDropdownName = document.getElementById('userMenuName');
  const userDropdownEmail = document.getElementById('userMenuEmail');
  const userAvatarImg = document.getElementById('userAvatarImg');
  const userAvatarLetter = document.getElementById('userAvatarLetter');
  const userMenuSavedCount = document.getElementById('userMenuSavedCount');
  const badgeSavedCount = document.getElementById('badgeSavedCount');
  const userMenuMyCount = document.getElementById('userMenuMyCount');
  const badgeMyCount = document.getElementById('badgeMyCount');
  const badgeDraftsCount = document.getElementById('badgeDraftsCount');
  const badgeChroniclesCount = document.getElementById('badgeChroniclesCount');
  const pillSaved = document.getElementById('pillSaved');
  const pillMyStories = document.getElementById('pillMyStories');
  const pillDrafts = document.getElementById('pillDrafts');
  const pillDailyChronicles = document.getElementById('pillDailyChronicles');

  const savedCount = savedPostIds.size;
  if (userMenuSavedCount) userMenuSavedCount.textContent = savedCount;
  if (badgeSavedCount) badgeSavedCount.textContent = savedCount;

  // Compute how many published stories, daily chronicles, and drafts belong to this user
  let myPostsCount = 0;
  let myChroniclesCount = 0;
  let myPosterDraftsCount = 0;
  if (Array.isArray(allPosts)) {
    const ownedPosts = allPosts.filter(p => isPostOwnedByCurrentUser(p));
    myChroniclesCount = ownedPosts.filter(p => isPostChronicleDiary(p) && !p.isDiaryDraftOnly).length;
    myPostsCount = ownedPosts.filter(p => !isPostChronicleDiary(p) && !isPostPrivateOrDraft(p)).length;
    myPosterDraftsCount = ownedPosts.filter(p =>
      (!isPostChronicleDiary(p) && isPostPrivateOrDraft(p)) ||
      (isPostChronicleDiary(p) && Boolean(p.isDiaryDraftOnly))
    ).length;
  }
  const myFormDraftsCount = typeof getSavedFormDrafts === 'function' ? getSavedFormDrafts().length : 0;
  const totalDraftsCount = myPosterDraftsCount + myFormDraftsCount;

  if (userMenuMyCount) userMenuMyCount.textContent = myPostsCount;
  if (badgeMyCount) badgeMyCount.textContent = myPostsCount;
  if (badgeDraftsCount) badgeDraftsCount.textContent = totalDraftsCount;
  if (badgeChroniclesCount) badgeChroniclesCount.textContent = myChroniclesCount;

  if (currentUser) {
    if (signedInView) signedInView.style.display = 'flex';
    if (signedOutView) signedOutView.style.display = 'none';
    document.body.classList.remove('signed-out-active');

    if (signInBtn) signInBtn.style.display = 'none';
    if (userMenuWrap) userMenuWrap.style.display = 'block';

    const displayName = getUserDisplayName();
    if (userDropdownName) userDropdownName.textContent = displayName;
    if (userDropdownEmail) userDropdownEmail.textContent = currentUser.email || '';

    const avatarUrl = getUserAvatarUrl();
    if (avatarUrl && userAvatarImg && userAvatarLetter) {
      userAvatarImg.src = avatarUrl;
      userAvatarImg.style.display = 'block';
      userAvatarLetter.style.display = 'none';
    } else if (userAvatarLetter) {
      userAvatarLetter.textContent = (displayName[0] || 'U').toUpperCase();
      if (userAvatarImg) userAvatarImg.style.display = 'none';
      userAvatarLetter.style.display = 'flex';
    }

    if (pillSaved) pillSaved.style.display = '';
    if (pillMyStories) pillMyStories.style.display = '';
    if (pillDrafts) pillDrafts.style.display = '';
    if (pillDailyChronicles) pillDailyChronicles.style.display = '';

    // Update Drawer Account UI
    const drawerAuthGuest = document.getElementById('drawerAuthGuest');
    const drawerAuthUser = document.getElementById('drawerAuthUser');
    const drawerUserName = document.getElementById('drawerUserName');
    const drawerUserEmail = document.getElementById('drawerUserEmail');
    const drawerUserAvatar = document.getElementById('drawerUserAvatar');
    const drawerSavedCount = document.getElementById('drawerSavedCount');
    const drawerMyCount = document.getElementById('drawerMyCount');
    const drawerDraftsCount = document.getElementById('drawerDraftsCount');

    if (drawerAuthGuest) drawerAuthGuest.style.display = 'none';
    if (drawerAuthUser) drawerAuthUser.style.display = 'flex';
    if (drawerUserName) drawerUserName.textContent = displayName;
    if (drawerUserEmail) drawerUserEmail.textContent = currentUser.email || '';
    if (drawerUserAvatar) drawerUserAvatar.textContent = (displayName[0] || 'U').toUpperCase();
    if (drawerSavedCount) drawerSavedCount.textContent = savedCount;
    if (drawerMyCount) drawerMyCount.textContent = myPostsCount;
    if (drawerDraftsCount) drawerDraftsCount.textContent = totalDraftsCount;

    if (typeof syncDrawerDiaryCounts === 'function') {
      syncDrawerDiaryCounts();
    }

    const drawerAdminBetaRow = document.getElementById('drawerAdminBetaRow');
    if (drawerAdminBetaRow) {
      drawerAdminBetaRow.style.display = isCurrentUserAdmin ? 'flex' : 'none';
    }

    const headerDiaryBtn = document.getElementById('headerDiaryBtn');
    if (headerDiaryBtn) {
      headerDiaryBtn.style.display = 'inline-flex';
    }
    if (typeof decryptAllOwnedChroniclePosts === 'function') {
      decryptAllOwnedChroniclePosts();
    }
    if (typeof maybeShowFirstLoginSlantDictionaryModal === 'function') {
      maybeShowFirstLoginSlantDictionaryModal();
    }
  } else {
    if (deepPostId) {
      if (signedInView) signedInView.style.display = 'flex';
      if (signedOutView) signedOutView.style.display = 'none';
      document.body.classList.remove('signed-out-active');
    } else {
      if (signedInView) signedInView.style.display = 'none';
      if (signedOutView) {
        signedOutView.style.display = 'flex';
        renderLoginPostsPreview();
      }
      document.body.classList.add('signed-out-active');
      dismissInitialFeedLoader(true);
      if (typeof initGoogleIdentityServices === 'function') {
        initGoogleIdentityServices();
      }
    }

    if (signInBtn) signInBtn.style.display = 'inline-flex';
    if (userMenuWrap) userMenuWrap.style.display = 'none';

    // Show saved pill if reader saved cards locally
    if (pillSaved) pillSaved.style.display = savedCount > 0 ? '' : 'none';
    if (pillMyStories) pillMyStories.style.display = myPostsCount > 0 ? '' : 'none';
    if (pillDrafts) pillDrafts.style.display = totalDraftsCount > 0 ? '' : 'none';
    if (pillDailyChronicles) pillDailyChronicles.style.display = myChroniclesCount > 0 ? '' : 'none';

    // Update Drawer Account UI for guest
    const drawerAuthGuest = document.getElementById('drawerAuthGuest');
    const drawerAuthUser = document.getElementById('drawerAuthUser');
    if (drawerAuthGuest) drawerAuthGuest.style.display = 'flex';
    if (drawerAuthUser) drawerAuthUser.style.display = 'none';

    const drawerAdminBetaRow = document.getElementById('drawerAdminBetaRow');
    if (drawerAdminBetaRow) drawerAdminBetaRow.style.display = 'none';

    const headerDiaryBtn = document.getElementById('headerDiaryBtn');
    if (headerDiaryBtn) headerDiaryBtn.style.display = 'inline-flex';
  }
}

let _slantDictTimers = [];

function clearSlantDictionaryTimers() {
  while (_slantDictTimers.length > 0) {
    clearTimeout(_slantDictTimers.pop());
  }
}

window.openSlantDictionaryModal = function(event) {
  if (event && typeof event.stopPropagation === 'function') {
    event.stopPropagation();
  }
  const modal = document.getElementById('slantDictionaryModal');
  if (!modal) return;
  modal.style.display = 'flex';
  window.replaySlantDictionaryAnimation();
};

window.closeSlantDictionaryModal = function() {
  clearSlantDictionaryTimers();
  const modal = document.getElementById('slantDictionaryModal');
  if (modal) {
    modal.style.display = 'none';
  }
};

window.replaySlantDictionaryAnimation = function() {
  clearSlantDictionaryTimers();
  const card = document.getElementById('slantDictPostcard');
  const queryEl = document.getElementById('slantDictTypedQuery');
  const cursorEl = document.getElementById('slantDictCursor');
  if (!card || !queryEl) return;

  card.classList.remove('phase-focus', 'phase-finale');
  const targetText = 'slant meaning';
  queryEl.textContent = '';
  if (cursorEl) cursorEl.style.display = 'inline';

  // Step 1: Typewriter effect for "slant meaning" (~650ms)
  for (let i = 1; i <= targetText.length; i++) {
    const t = setTimeout(() => {
      queryEl.textContent = targetText.slice(0, i);
    }, i * 48);
    _slantDictTimers.push(t);
  }

  // Step 2: Fade out Geometry Sense #1 and Illuminate Verb & Noun Sense #2 (~1050ms)
  _slantDictTimers.push(setTimeout(() => {
    card.classList.add('phase-focus');
    if (cursorEl) cursorEl.style.display = 'none';
  }, 1050));

  // Step 3: Reveal Finale Quote & "Happy Slanting ✦" CTA (~1850ms)
  _slantDictTimers.push(setTimeout(() => {
    card.classList.add('phase-finale');
  }, 1850));
};

function maybeShowFirstLoginSlantDictionaryModal() {
  if (!currentUser || !currentUser.id) return;
  const deepPostId = typeof getDeepLinkedPostId === 'function' ? getDeepLinkedPostId() : null;
  if (deepPostId) return;

  const storageKey = 'slant_dict_welcome_seen_v1_' + currentUser.id;
  try {
    if (localStorage.getItem(storageKey) === '1') return;
    localStorage.setItem(storageKey, '1');
  } catch (e) {
    return;
  }

  setTimeout(() => {
    const signedInView = document.getElementById('signedInAppView');
    if (signedInView && signedInView.style.display !== 'none') {
      window.openSlantDictionaryModal();
    }
  }, 650);
}

let isAuthPasswordMode = false;

function togglePasswordMode(isPassword) {
  isAuthPasswordMode = (isPassword === true);
  const wrap = document.getElementById('loginPasswordWrap');
  const helper = document.getElementById('authHelperText');
  const submitBtn = document.getElementById('emailAuthBtn');
  const altRow = document.getElementById('authAltRow');
  const passwordInput = document.getElementById('loginPasswordInput');

  if (isAuthPasswordMode) {
    if (wrap) wrap.style.display = 'block';
    if (helper) helper.textContent = 'Enter your email & password to sign into your Slant account.';
    if (submitBtn) submitBtn.innerHTML = '<span>Sign In with Password &rarr;</span>';
    if (altRow) {
      altRow.innerHTML = `
        <button type="button" class="auth-toggle-btn" onclick="togglePasswordMode(false)">
          Prefer passwordless? Send Magic Link instead
        </button>
      `;
    }
    if (passwordInput) passwordInput.focus();
  } else {
    if (wrap) wrap.style.display = 'none';
    if (helper) helper.textContent = "We'll send an instant passwordless magic link to your email.";
    if (submitBtn) submitBtn.innerHTML = '<span>Send Magic Link &rarr;</span>';
    if (altRow) {
      altRow.innerHTML = `
        <button type="button" class="auth-toggle-btn" id="togglePasswordModeBtn" onclick="togglePasswordMode(true)">
          Have a password? Sign in with password
        </button>
      `;
    }
  }
}

