let currentSampleStoryIndex = 0;
let sampleCarouselAutoPlayTimer = null;
let isSampleCarouselHovered = false;
let currentLoginPillarIndex = 0;
let loginPillarAutoPlayTimer = null;
let isLoginPillarHovered = false;

let currentLoginPerspectiveSpark = 'web';

function setLoginPerspectiveSpark(sparkType) {
  currentLoginPerspectiveSpark = (sparkType === 'voice') ? 'voice' : 'web';
  const isVoice = (currentLoginPerspectiveSpark === 'voice');
  const chipWeb = document.getElementById('loginSparkChipWeb');
  const chipVoice = document.getElementById('loginSparkChipVoice');
  const visualImg = document.getElementById('loginPerspectiveVisualImg');
  const bodyIcon = document.getElementById('loginPerspectiveBodyIcon');
  const tabIcon = document.getElementById('loginPerspectiveTabIcon');
  const hookEl = document.getElementById('loginPerspectiveHook');
  const descEl = document.getElementById('loginPerspectiveDesc');

  if (chipWeb) chipWeb.classList.toggle('active', !isVoice);
  if (chipVoice) chipVoice.classList.toggle('active', isVoice);
  const iconSrc = isVoice ? '/slant-icon-innervoice.jpg?v=20261028_1645' : '/slant-icon-weblink.jpg?v=20261028_1645';
  if (visualImg) {
    visualImg.src = isVoice ? '/slant-pillar-innervoice.jpg?v=20261028_1645' : '/slant-pillar-weblink.jpg?v=20261028_1645';
  }
  if (bodyIcon) bodyIcon.src = iconSrc;
  if (tabIcon) tabIcon.src = iconSrc;
  if (hookEl) {
    hookEl.textContent = isVoice
      ? 'On an observation, experience, or conviction on your mind.'
      : 'On what you read or watch on the web, in a few lines.';
  }
  if (descEl) {
    descEl.textContent = 'Slant frames it into shareable illustrated posters, keeping your style and voice intact.';
  }
}

function goToLoginPillarSlide(pillarIdx) {
  const viewport = document.getElementById('loginPillarsCarousel');
  const track = document.getElementById('loginPillarsTrack');
  if (!viewport || !track) return;
  const total = 2;
  const normalized = ((pillarIdx % total) + total) % total;
  currentLoginPillarIndex = normalized;
  viewport.setAttribute('data-current-pillar', String(normalized));
  track.style.transform = `translateX(-${normalized * (100 / total)}%)`;

  document.querySelectorAll('#loginPillarsSwitcher .pillar-switch-pill').forEach((pill, i) => {
    pill.classList.toggle('active', i === normalized);
  });
  document.querySelectorAll('#loginPillarsDots .carousel-dot').forEach((dot, i) => {
    dot.classList.toggle('active', i === normalized);
  });
}

function stepLoginPillarSlide(delta) {
  goToLoginPillarSlide(currentLoginPillarIndex + (delta || 1));
}

function setupLoginPillarsCarousel() {
  const viewport = document.getElementById('loginPillarsCarousel');
  if (!viewport) return;
  if (!viewport.dataset.gesturesBound) {
    viewport.dataset.gesturesBound = 'true';
    viewport.addEventListener('mouseenter', () => { isLoginPillarHovered = true; });
    viewport.addEventListener('mouseleave', () => { isLoginPillarHovered = false; });

    let startX = 0;
    let startY = 0;
    viewport.addEventListener('touchstart', (e) => {
      isLoginPillarHovered = true;
      if (e.touches && e.touches[0]) {
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
      }
    }, { passive: true });

    viewport.addEventListener('touchend', (e) => {
      setTimeout(() => { isLoginPillarHovered = false; }, 3500);
      if (e.changedTouches && e.changedTouches[0]) {
        const dx = e.changedTouches[0].clientX - startX;
        const dy = e.changedTouches[0].clientY - startY;
        if (Math.abs(dx) > 36 && Math.abs(dx) > Math.abs(dy)) {
          stepLoginPillarSlide(dx < 0 ? 1 : -1);
        }
      }
    }, { passive: true });
  }

  goToLoginPillarSlide(currentLoginPillarIndex || 0);

  if (loginPillarAutoPlayTimer) {
    clearInterval(loginPillarAutoPlayTimer);
  }
  loginPillarAutoPlayTimer = setInterval(() => {
    if (isLoginPillarHovered) return;
    const signedOutView = document.getElementById('signedOutPageView');
    if (!signedOutView || signedOutView.style.display === 'none') {
      clearInterval(loginPillarAutoPlayTimer);
      return;
    }
    if (currentLoginPillarIndex === 0 && currentLoginPerspectiveSpark === 'web') {
      setLoginPerspectiveSpark('voice');
    } else if (currentLoginPillarIndex === 0 && currentLoginPerspectiveSpark === 'voice') {
      goToLoginPillarSlide(1);
    } else {
      setLoginPerspectiveSpark('web');
      goToLoginPillarSlide(0);
    }
  }, 4500);
}

function renderLoginPostsPreview() {
  const track = document.getElementById("loginPostsScrollTrack");
  const switcher = document.getElementById("loginStoriesSwitcher");
  const samplesGrid = document.getElementById("loginSampleCarouselsGrid");
  const pillarsViewport = document.getElementById("loginPillarsCarousel");
  if (pillarsViewport) {
    setupLoginPillarsCarousel();
  }
  if (!track && !samplesGrid) return;

  // Keep featured login sample posts strictly on the login showcase and out of the user's account/feed
  if (typeof myCreatedPostIds !== 'undefined' && myCreatedPostIds.size > 0) {
    LOGIN_SHOWCASE_ONLY_POST_IDS.forEach(id => myCreatedPostIds.delete(id));
  }

  // Find the selected colourful posts strictly matching FEATURED_COLORFUL_POST_CONFIGS
  const selectedPosts = [];
  FEATURED_COLORFUL_POST_CONFIGS.forEach(cfg => {
    const post = (FEATURED_LOGIN_POSTS || []).find(p => p && p.id === cfg.id) ||
      (allPosts || []).find(p => p && p.id === cfg.id);
    if (post) {
      selectedPosts.push({ post, cfg });
    }
  });

  // Fallback if some IDs are missing
  if (selectedPosts.length === 0 && Array.isArray(allPosts)) {
    allPosts.slice(0, 4).forEach((post, i) => {
      selectedPosts.push({
        post,
        cfg: { id: post.id, icon: "📰", shortName: post.categoryBadge || ("Story " + (i + 1)) }
      });
    });
  }

  window._selectedSamplePosts = selectedPosts;

  // 1. Build Story Switcher Pills (if present)
  if (switcher) {
    switcher.innerHTML = '';
    selectedPosts.forEach(({ post, cfg }, idx) => {
      const pill = document.createElement('button');
      pill.type = 'button';
      pill.className = `story-switch-pill ${idx === currentSampleStoryIndex ? 'active' : ''}`;
      pill.id = `storyPill-${post.id}`;
      pill.innerHTML = `<span>${cfg.icon}</span> <span>${escapeHtml(cfg.shortName)}</span>`;
      pill.onclick = () => {
        selectSampleStory(idx);
      };
      switcher.appendChild(pill);
    });
  }

  // 2. Render lower 4-card sample showcase grid (single-page scroll flow)
  if (samplesGrid) {
    renderLoginSamplesGrid(selectedPosts);
  }

  // 3. Render initial sample story into single track if present
  if (track) {
    renderSampleStory(currentSampleStoryIndex);
  }
  startSampleCarouselAutoPlay();
}

