// Backward compatibility alias
function renderFamilyCastModalList() {
  renderVaultMemberTabs();
  renderActiveMemberScreen();
}

function resetFamilyCastToDefault() {
  familyCastProfileCache = getDefaultClientFamilyCast();
  const memberIds = (familyCastProfileCache.members || []).map(m => m.id);
  activeCastMemberIds = new Set(memberIds);
  activeVaultMemberId = memberIds[0] || null;
  saveFamilyCastProfile(familyCastProfileCache);
  renderVaultMemberTabs();
  renderActiveMemberScreen();
  renderFamilyCastStagingUI();
  showTemporaryToast(
    memberIds.length > 0
      ? '✓ Reset to standard family blueprint'
      : '✓ Cleared personal family vault'
  );
}

function setFamilyCastStagingMode(mode) {
  activeCastStagingMode = mode || 'general';
  [
    ['stagingPillRhd', 'vehicle_rhd'],
    ['stagingPillOverlook', 'scenic_overlook'],
    ['stagingPillDomestic', 'general'],
    ['eqStagingPillRhd', 'vehicle_rhd'],
    ['eqStagingPillOverlook', 'scenic_overlook'],
    ['eqStagingPillDomestic', 'general']
  ].forEach(([id, targetMode]) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.toggle('active', mode === targetMode);
  });
  if (typeof evaluateSmartRegenScopeAutoSwitch === 'function') {
    evaluateSmartRegenScopeAutoSwitch();
  }
}

function toggleActiveCastMember(memberId) {
  window._userManuallyToggledCast = true;
  if (activeCastMemberIds.has(memberId)) {
    activeCastMemberIds.delete(memberId);
  } else {
    activeCastMemberIds.add(memberId);
  }
  renderFamilyCastStagingUI();
  if (typeof evaluateSmartRegenScopeAutoSwitch === 'function') {
    evaluateSmartRegenScopeAutoSwitch();
  }
}

function clearActiveCastSelection() {
  window._userManuallyToggledCast = true;
  activeCastMemberIds.clear();
  const hint = document.getElementById('familyCastAutoHint');
  const eqHint = document.getElementById('equalizerCastAutoHint');
  if (hint) hint.style.display = 'none';
  if (eqHint) eqHint.style.display = 'none';
  renderFamilyCastStagingUI();
  showTemporaryToast('Cleared selected cast members for this post.');
}

function detectRelevantCastMembers(text = '', cast = null) {
  const combined = String(text || '').toLowerCase();
  const profile = cast || familyCastProfileCache || getDefaultClientFamilyCast();
  const members = (profile && Array.isArray(profile.members)) ? profile.members : [];

  // 0. First-Person Separation / Solitude Scene:
  // When the narrator (Father / Self) writes that he is alone, stuck in one city while wife/kids are away,
  // or missing/waiting for them to return, the present-tense visual HERO is exclusively Father / Self (Shridhar)!
  const isNarratorAloneMissingFamily = /\b(i am alone|being alone|stuck in [a-z]+ while|miss them|missing them|how much i miss|waiting for them|when my wife is out|feeling of separation|feeling of separateness)\b/i.test(combined);
  if (isNarratorAloneMissingFamily) {
    const selfMember = members.find(m => m.relationship === 'self') || { id: 'member_father' };
    return new Set([selfMember.id]);
  }

  // Strictly require first-person possessives ("my/our") so general societal observations ("the whole family comes", "the kids") NEVER trigger personal family photos
  const mentionsCollective = /\b(my family|our family|my whole family|our whole family|my entire family|our entire family|the four of us|all four of us|road trip with my family|vacation with my family|walk.*with my family)\b/i.test(combined);
  if (mentionsCollective) {
    return new Set(members.map(m => m.id));
  }

  // Detect when the author refers to their own two sons ("my kids", "my boys", "my sons", or in a personal Chronicle / household context "kids fighting", "boys fighting", etc.)
  const isSchoolOrSocietalObservation = /\b(parent-teacher|ptm|second-grade|school days|teachers' meeting|classroom|students in)\b/i.test(combined);
  const isFirstPersonHouseholdKids = !isSchoolOrSocietalObservation && (
    /\b(my kids|our kids|both my kids|both our kids|my sons|our sons|both my sons|both our sons|both my boys|both our boys|my boys|our boys|my children|our children|both boys|both sons|two sons|two boys)\b/i.test(combined) ||
    (isDailyChronicleMode && /\b(kids|boys|sons|children|brothers)\b/i.test(combined)) ||
    (/\b(my day|started with|at home|in the morning|helping resolve|witnessing)\b/i.test(combined) && /\b(kids fighting|boys fighting|kids arguing|kids playing|kids at home)\b/i.test(combined))
  );

  const detected = new Set();
  if (isFirstPersonHouseholdKids) {
    const elder = members.find(m => m.relationship === 'elder_son');
    const younger = members.find(m => m.relationship === 'younger_son');
    if (elder) detected.add(elder.id);
    if (younger) detected.add(younger.id);
  }

  members.forEach(m => {
    // 1. Vault Name Tokens (e.g. "shridhar")
    const nameStr = String(m.name || '').toLowerCase();
    const cleanName = nameStr.replace(/[^a-z0-9\s]/g, ' ').trim();
    const nameWords = cleanName.split(/\s+/).filter(w => w.length > 2 && !['father', 'mother', 'elder', 'younger', 'self', 'son'].includes(w));
    for (const w of nameWords) {
      if (new RegExp(`\\b${w}\\b`, 'i').test(combined)) {
        detected.add(m.id);
        break;
      }
    }

    // 2. Vault Aliases (e.g. "rishu", "gahan", "aru")
    const aliases = Array.isArray(m.aliases) ? m.aliases : [];
    for (const alias of aliases) {
      const a = String(alias || '').trim().toLowerCase();
      if (!a || a.length < 2 || ['i', 'me', 'my', 'myself'].includes(a)) continue;
      const safe = a.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
      if (new RegExp(`\\b${safe}\\b`, 'i').test(combined)) {
        detected.add(m.id);
        break;
      }
    }

    // 3. Role-specific semantic keywords (STRICTLY first-person personal possessives or explicit family names)
    if (m.relationship === 'elder_son') {
      if (isFirstPersonHouseholdKids || /\b(my elder son|my older son|my older boy|my first son|my 11-year-old|my 11yo|gahan|my kids|our kids|my boys|our boys|my sons|our sons|my children|our children)\b/i.test(combined)) {
        detected.add(m.id);
      }
    } else if (m.relationship === 'younger_son') {
      if (isFirstPersonHouseholdKids || /\b(my younger son|my little son|my younger boy|my second son|my 7-year-old|my 7yo|rishu|my kids|our kids|my boys|our boys|my sons|our sons|my children|our children)\b/i.test(combined)) {
        detected.add(m.id);
      }
    } else if (m.relationship === 'spouse') {
      if (/\b(my wife|my spouse|with my wife|aru|aruna)\b/i.test(combined)) {
        detected.add(m.id);
      }
    } else if (m.relationship === 'self') {
      if (/\b(shridhar)\b/i.test(combined)) {
        detected.add(m.id);
      }
    }
  });

  // 4. First-Person Narrator Participation alongside detected spouse or children, OR Diary Chronicle mode
  const hasChild = detected.has('member_elder_son') || detected.has('member_younger_son');
  const hasSpouse = detected.has('member_mother');
  const hasFirstPersonCoPresence = /\b(and me|with me|between .* and me|i remain|by my side|by his side|beside him|beside her|holding my hand|teaching him|walked with him|support him|i stood|standing beside|my home|my life|my day|helping resolve|witnessing|attended|launched)\b/i.test(combined);
  if ((hasChild || hasSpouse) && (hasFirstPersonCoPresence || isDailyChronicleMode)) {
    detected.add('member_father');
  }

  if (isDailyChronicleMode) {
    const selfMember = members.find(m => m.relationship === 'self') || { id: 'member_father' };
    detected.add(selfMember.id);
  }

  return detected;
}

function dismissFamilyCastStaging() {
  clearActiveCastSelection();
}

function manuallyOpenFamilyCastStaging() {
  const card = document.getElementById('familyCastStagingCard');
  const launcher = document.getElementById('familyCastLauncherWrap');
  if (card) {
    card.style.display = 'flex';
    card.dataset.manuallyOpened = 'true';
    delete card.dataset.manuallyDismissed;
  }
  if (launcher) launcher.style.display = 'none';

  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  if (activeCastMemberIds.size === 0 && (cast.members || []).length > 0) {
    activeCastMemberIds.add(cast.members[0].id);
  }
  renderFamilyCastStagingUI();
}

function checkAndTriggerFamilyCast(text = '') {
  const combined = String(text || '').toLowerCase();
  const card = document.getElementById('familyCastStagingCard');
  const launcher = document.getElementById('familyCastLauncherWrap');
  const hint = document.getElementById('familyCastAutoHint');
  const eqHint = document.getElementById('equalizerCastAutoHint');
  if (card) card.style.display = 'flex';
  if (launcher) launcher.style.display = 'none';

  if (window._userManuallyToggledCast) {
    renderFamilyCastStagingUI();
    return;
  }

  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const detectedIds = detectRelevantCastMembers(combined, cast);

  if (detectedIds.size > 0) {
    activeCastMemberIds = detectedIds;
    renderFamilyCastStagingUI();

    const names = (cast.members || []).filter(m => detectedIds.has(m.id)).map(m => m.name || m.roleLabel);
    const hintHtml = `<span>🎯 Auto-identified from Vault: <strong>${escapeHtml(names.join(' & '))}</strong></span>`;
    if (hint) {
      hint.style.display = 'block';
      hint.innerHTML = hintHtml;
    }
    if (eqHint) {
      eqHint.style.display = 'block';
      eqHint.innerHTML = hintHtml;
    }

    // Auto-detect vehicle context
    if (/\b(car|drive|driving|road trip|vehicle|suv|sedan|highway)\b/i.test(combined)) {
      if (/\b(overlook|viewpoint|hills|mountains)\b/i.test(combined)) {
        setFamilyCastStagingMode('scenic_overlook');
      } else {
        setFamilyCastStagingMode('vehicle_rhd');
      }
    } else {
      setFamilyCastStagingMode('general');
    }
  } else {
    activeCastMemberIds.clear();
    if (hint) hint.style.display = 'none';
    if (eqHint) eqHint.style.display = 'none';
    renderFamilyCastStagingUI();
  }
}

function renderFamilyCastStagingUI() {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const members = (cast.members || []).filter(m => m && (m.name || m.roleLabel !== 'New Member'));

  const chipsHtml = members.map(m => {
    const isActive = activeCastMemberIds.has(m.id);
    const avatarSrc = m.photoBase64 || m.stylizedAvatarUrl || '';
    const avatarThumb = avatarSrc ? `<img src="${avatarSrc}" class="chip-avatar-img" alt="">` : '';
    const ageLabel = m.age ? ` (${m.age})` : '';
    return `
      <div class="family-cast-chip ${isActive ? 'active' : ''}" onclick="toggleActiveCastMember('${m.id}')" title="Toggle ${escapeHtml(m.name || m.roleLabel)}">
        <span class="chip-check">${isActive ? '✓' : '+'}</span>
        ${avatarThumb}
        <span>${escapeHtml((m.name || m.roleLabel) + ageLabel)}</span>
      </div>
    `;
  }).join('');

  ['familyCastMembersRow', 'equalizerCastMembersRow'].forEach(containerId => {
    const el = document.getElementById(containerId);
    if (el) el.innerHTML = chipsHtml;
  });

  const hasElder = activeCastMemberIds.has('member_elder_son') || members.some(m => activeCastMemberIds.has(m.id) && m.age === 11);
  const hasYounger = activeCastMemberIds.has('member_younger_son') || members.some(m => activeCastMemberIds.has(m.id) && m.age === 7);

  const banner = document.getElementById('familyCastAgeBanner');
  if (banner) {
    if (hasElder && hasYounger) {
      banner.style.display = 'flex';
      banner.innerHTML = `
        <span class="guarantee-icon">✨</span>
        <span class="guarantee-text"><strong>4-Year Age Gap Enforced:</strong> 11-year-old pre-teen (taller, sturdy healthy build) vs 7-year-old young child (shorter by a head, round child cheeks). Strictly no identical twins.</span>
      `;
    } else {
      banner.style.display = 'none';
    }
  }
}

function getActiveCastPayload() {
  const cast = familyCastProfileCache || getDefaultClientFamilyCast();
  const activeList = (cast.members || []).filter(m => activeCastMemberIds.has(m.id));
  if (activeList.length === 0) {
    return null;
  }
  return {
    members: activeList,
    stagingMode: activeCastStagingMode,
    manuallySelected: Boolean(window._userManuallyToggledCast)
  };
}

function getSanitizedCastMember(m) {
  if (!m) return null;
  return {
    id: m.id,
    name: m.name,
    relationship: m.relationship,
    roleLabel: m.roleLabel,
    aliases: m.aliases,
    age: m.age,
    heightCm: resolveMemberHeightCm(m),
    heightDesc: m.heightDesc,
    structuredTraits: m.structuredTraits || null,
    uncompromisableAnchors: m.uncompromisableAnchors,
    visualTraits: m.visualTraits,
    vehicleRole: m.vehicleRole,
    stylizedAvatarUrl: m.stylizedAvatarUrl
  };
}

function getSanitizedCastPayload(cast) {
  if (!cast) return null;
  return {
    userIdentifier: cast.userIdentifier || '',
    updatedAt: cast.updatedAt || '',
    collectiveAliases: cast.collectiveAliases || [],
    members: (cast.members || []).map(getSanitizedCastMember)
  };
}

function getSanitizedActiveCastPayload() {
  const activePayload = getActiveCastPayload();
  if (!activePayload) return null;
  return {
    stagingMode: activePayload.stagingMode,
    manuallySelected: Boolean(activePayload.manuallySelected),
    members: (activePayload.members || []).map(getSanitizedCastMember)
  };
}

// --- Daily Chronicle (Multi-Moment Collage) State & Helpers ---
let isDailyChronicleMode = false;
let activeChroniclePhotoUploadIdx = -1;
let dailyChronicleMoments = [
  { id: 1, title: '', text: '', isStarred: false, imageBase64: null, imageMimeType: 'image/jpeg' },
  { id: 2, title: '', text: '', isStarred: false, imageBase64: null, imageMimeType: 'image/jpeg' },
  { id: 3, title: '', text: '', isStarred: true, imageBase64: null, imageMimeType: 'image/jpeg' }
];

function setInnerVoiceSubmode(submode) {
  if (submode === 'chronicle') {
    setAnchorMode('diary_chronicle');
  } else {
    setAnchorMode('inner_voice');
  }
}

function syncInnerVoiceSubmodeUI() {
  const isVoice = (creatorSelectedSource === 'inner_voice');
  const singleBtn = document.getElementById('innerVoiceSubSingleBtn');
  const chronBtn = document.getElementById('innerVoiceSubChronicleBtn');
  const singleSparkWrap = document.getElementById('innerVoiceSingleSparkWrap');
  const chronBanner = document.getElementById('dailyChronicleIntroBanner');
  const slantTextarea = document.getElementById('creatorSlantTakeInput');
  const chronDeck = document.getElementById('dailyChronicleDeckWrap');
  const label = document.getElementById('slantTakeLabel');
  const sub = document.getElementById('slantTakeSubtitle');
  const heroIcon = document.getElementById('slantHeroIcon');
  const heroBox = document.getElementById('slantIconBox');

  if (singleBtn) singleBtn.classList.toggle('active', !isDailyChronicleMode);
  if (chronBtn) chronBtn.classList.toggle('active', isDailyChronicleMode);

  const secVoice = document.getElementById('triggerVoiceSection');
  const triggerPanel = secVoice ? secVoice.closest('.creator-trigger-panel') : null;
  const guideBtn = document.getElementById('slantGuideToggleBtn');
  const guideCard = document.getElementById('slantStructureGuideCard');

  if (!isVoice) {
    if (triggerPanel) triggerPanel.style.display = '';
    if (slantTextarea) slantTextarea.style.display = 'block';
    if (chronDeck) chronDeck.style.display = 'none';
    if (guideBtn) guideBtn.style.display = 'inline-flex';
    return;
  }

  if (isDailyChronicleMode) {
    if (singleSparkWrap) singleSparkWrap.style.display = 'none';
    if (chronBanner) chronBanner.style.display = 'none';
    if (secVoice) secVoice.style.display = 'none';
    if (triggerPanel) triggerPanel.style.display = 'none';
    if (slantTextarea) slantTextarea.style.display = 'none';
    if (chronDeck) chronDeck.style.display = 'flex';
    if (guideBtn) {
      guideBtn.style.display = 'none';
      guideBtn.classList.remove('active');
    }
    if (guideCard) guideCard.style.display = 'none';
    if (label) label.textContent = 'Your Day in Moments';
    if (sub) sub.textContent = 'Record 2 to 3 distinct moments from your day. Tap ★ Star on your main moment to give it the largest space in Poster 1. 🔒 End-to-end AES-256 encrypted.';
    if (heroIcon) heroIcon.textContent = '📔';
    if (heroBox) heroBox.style.color = '#253833';

    // Default portrayal style for Diary Chronicle is Painted Vignettes (matching 4bovq style)
    if (typeof selectCharacterRep === 'function') {
      selectCharacterRep('painting');
    }

    // Always ensure Father (Shridhar, 40yo) is active in Family Cast as the center of the Daily Chronicle collage
    activeCastMemberIds.add('member_father');
    renderFamilyCastStagingUI();
    renderDailyChronicleCards();
    syncChronicleMomentsToSlantInput();
  } else {
    if (triggerPanel) triggerPanel.style.display = '';
    if (secVoice) secVoice.style.display = 'flex';
    if (singleSparkWrap) singleSparkWrap.style.display = 'block';
    if (chronBanner) chronBanner.style.display = 'none';
    if (slantTextarea) slantTextarea.style.display = 'block';
    if (chronDeck) chronDeck.style.display = 'none';
    if (guideBtn) guideBtn.style.display = 'inline-flex';
    if (label) label.textContent = 'Your Perspective';
    if (sub) sub.textContent = 'Express your conviction or reflection freely. AI frames 100% of your voice into your 3-poster story.';
    if (heroIcon) heroIcon.textContent = '💭';
    if (heroBox) heroBox.style.color = '#253833';
  }
  if (typeof syncStep3SaveButtonLabel === 'function') {
    syncStep3SaveButtonLabel();
  }
  if (typeof autoIdentifyVisualProjectionsFromInput === 'function') {
    autoIdentifyVisualProjectionsFromInput(true);
  }
}

function renderDailyChronicleCards() {
  const container = document.getElementById('dailyChronicleCardsList');
  if (!container) return;

  if (dailyChronicleMoments.length > 3) {
    dailyChronicleMoments = dailyChronicleMoments.slice(0, 3);
  }

  const placeholders = [
    { title: 'e.g. Morning Walk / Routine', text: 'Write 2-3 lines about your first key moment of the day...' },
    { title: 'e.g. Work / Midday Observation', text: 'Write 2-3 lines about the second moment or conversation...' },
    { title: 'e.g. Family / Evening Reflection', text: 'Write 2-3 lines about the third moment that stayed with you...' }
  ];

  container.innerHTML = dailyChronicleMoments.map((m, idx) => {
    const numStr = String(idx + 1).padStart(2, '0');
    const ph = placeholders[idx] || placeholders[0];
    const hasPhoto = Boolean(m.imageBase64);
    const isStarred = Boolean(m.isStarred);
    const canDelete = dailyChronicleMoments.length > 2;

    const starBtnHtml = `<button type="button" class="chronicle-moment-star-btn ${isStarred ? 'is-starred' : ''}" onclick="toggleChronicleMomentStar(${idx}, event)" title="${isStarred ? 'Starred as the most important moment (gets larger showcase space in Poster 1)' : 'Star this moment if you feel it is the most important (gives it more space in Poster 1)'}">
      <span class="chronicle-star-icon">${isStarred ? '★' : '☆'}</span>
      <span class="chronicle-star-label">${isStarred ? 'Starred' : 'Star'}</span>
    </button>`;

    const photoActionHtml = hasPhoto
      ? `<div class="chronicle-moment-photo-chip">
           <img src="${m.imageBase64}" class="chronicle-moment-thumb" alt="Moment ${numStr}">
           <span>✓ Photo</span>
           <button type="button" class="chronicle-moment-photo-remove" onclick="removeChronicleMomentPhoto(${idx}, event)" title="Remove photo">&times;</button>
         </div>`
      : `<button type="button" class="chronicle-moment-photo-btn" onclick="triggerChronicleMomentPhoto(${idx})">
           <span>📷</span>
           <span>Attach Photo</span>
         </button>`;

    const deleteBtnHtml = canDelete
      ? `<button type="button" class="chronicle-moment-delete-btn" onclick="removeDailyChronicleMoment(${idx})" title="Remove this moment card">✕</button>`
      : '';

    return `
      <div class="chronicle-moment-card ${isStarred ? 'is-starred-moment' : ''}" data-moment-idx="${idx}">
        <div class="chronicle-moment-card-header">
          <div class="chronicle-moment-left">
            <span class="chronicle-moment-num-badge">MOMENT ${numStr}</span>
          </div>
          <div class="chronicle-moment-actions">
            ${starBtnHtml}
            ${photoActionHtml}
            ${deleteBtnHtml}
          </div>
        </div>
        <textarea
          class="chronicle-moment-textarea"
          rows="2"
          placeholder="${escapeHtml(ph.text)}"
          oninput="onChronicleMomentInput(${idx}, 'text', this.value)"
        >${escapeHtml(m.text || '')}</textarea>
      </div>
    `;
  }).join('');

  const addBtn = document.getElementById('chronicleAddMomentBtn');
  const addTxt = document.getElementById('chronicleAddMomentBtnText');
  const countHint = document.getElementById('chronicleMomentsCountHint');
  const count = dailyChronicleMoments.length;
  const photosCount = dailyChronicleMoments.filter(m => Boolean(m.imageBase64)).length;
  const starredIdx = dailyChronicleMoments.findIndex(m => Boolean(m.isStarred));

  if (addBtn) {
    addBtn.style.display = count >= 3 ? 'none' : 'inline-flex';
    if (addTxt) addTxt.textContent = 'Add 3rd Moment';
  }
  if (countHint) {
    const starText = starredIdx >= 0 ? `★ Moment 0${starredIdx + 1} Starred` : '';
    countHint.textContent = `${count} / 3 Moments${photosCount > 0 ? ` • ${photosCount} Photo${photosCount > 1 ? 's' : ''}` : ''}${starText ? ` • ${starText}` : ''}`;
  }
}

function toggleChronicleMomentStar(idx, event) {
  if (event) event.stopPropagation();
  if (!dailyChronicleMoments[idx]) return;
  const nextVal = !dailyChronicleMoments[idx].isStarred;
  dailyChronicleMoments.forEach((m, i) => {
    m.isStarred = (i === idx) ? nextVal : false;
  });
  renderDailyChronicleCards();
  syncChronicleMomentsToSlantInput();
  if (nextVal && typeof showTemporaryToast === 'function') {
    showTemporaryToast(`★ Moment 0${idx + 1} marked as important! It will get the larger showcase space in Poster 1.`);
  }
  if (typeof evaluateSmartRegenScopeAutoSwitch === 'function') {
    evaluateSmartRegenScopeAutoSwitch();
  }
}

function onChronicleMomentInput(idx, field, val) {
  if (!dailyChronicleMoments[idx]) return;
  dailyChronicleMoments[idx][field] = val;
  if (typeof clearCreatorPromptReadyGlow === 'function' && String(val || '').trim().length > 0) {
    clearCreatorPromptReadyGlow();
  }
  syncChronicleMomentsToSlantInput();
  if (typeof autoIdentifyVisualProjectionsFromInput === 'function') {
    autoIdentifyVisualProjectionsFromInput(false);
  }
  if (typeof evaluateSmartRegenScopeAutoSwitch === 'function') {
    evaluateSmartRegenScopeAutoSwitch();
  }
}

function syncChronicleMomentsToSlantInput() {
  if (!isDailyChronicleMode) return;
  const input = document.getElementById('creatorSlantTakeInput');
  if (!input) return;

  const lines = dailyChronicleMoments
    .map((m, idx) => {
      const txt = String(m.text || '').trim();
      if (!txt) return '';
      const numStr = String(idx + 1).padStart(2, '0');
      return `Moment ${numStr}: ${txt}`;
    })
    .filter(Boolean);

  input.value = lines.join('\n\n');
  checkAndTriggerFamilyCast(input.value);
  activeCastMemberIds.add('member_father');
  renderFamilyCastStagingUI();
}

function addDailyChronicleMoment() {
  if (dailyChronicleMoments.length >= 3) {
    showTemporaryToast('Maximum 3 moments per Daily Chronicle so each vignette stays crisp.');
    return;
  }
  dailyChronicleMoments.push({
    id: Date.now(),
    title: '',
    text: '',
    isStarred: false,
    imageBase64: null,
    imageMimeType: 'image/jpeg'
  });
  renderDailyChronicleCards();
  syncChronicleMomentsToSlantInput();
}

function removeDailyChronicleMoment(idx) {
  if (dailyChronicleMoments.length <= 2) {
    showTemporaryToast('A Daily Chronicle requires at least 2 moments.');
    return;
  }
  dailyChronicleMoments.splice(idx, 1);
  renderDailyChronicleCards();
  syncChronicleMomentsToSlantInput();
}

function triggerChronicleMomentPhoto(idx) {
  activeChroniclePhotoUploadIdx = idx;
  const fileInput = document.getElementById('chronicleMomentFileInput');
  if (fileInput) {
    fileInput.value = '';
    fileInput.click();
  }
}

function handleChronicleMomentPhotoSelect(event) {
  const file = event.target?.files?.[0];
  if (!file || activeChroniclePhotoUploadIdx < 0 || !dailyChronicleMoments[activeChroniclePhotoUploadIdx]) return;
  const targetIdx = activeChroniclePhotoUploadIdx;

  compressImage(file, 900, 0.82, (compressedDataUrl) => {
    dailyChronicleMoments[targetIdx].imageBase64 = compressedDataUrl;
    dailyChronicleMoments[targetIdx].imageMimeType = 'image/jpeg';
    renderDailyChronicleCards();
    updateReferencePhotoUI();
    showTemporaryToast(`📸 Attached photo to Moment 0${targetIdx + 1}!`);
  });
}

function removeChronicleMomentPhoto(idx, event) {
  if (event) event.stopPropagation();
  if (!dailyChronicleMoments[idx]) return;
  dailyChronicleMoments[idx].imageBase64 = null;
  renderDailyChronicleCards();
  updateReferencePhotoUI();
}

function getActiveChronicleMomentsPayload() {
  if (creatorSelectedSource !== 'inner_voice' || !isDailyChronicleMode) return [];
  return dailyChronicleMoments
    .map((m, idx) => ({
      index: idx + 1,
      title: String(m.title || '').trim() || `Moment 0${idx + 1}`,
      text: String(m.text || '').trim(),
      isStarred: Boolean(m.isStarred),
      imageBase64: m.imageBase64 || null,
      imageMimeType: m.imageMimeType || 'image/jpeg',
      preferredVisualProjection: m.preferredVisualProjection || null
    }))
    .filter(m => m.text.length >= 2);
}

async function buildClientExactChronicleCollage(momentsWithPhotos) {
  const photos = (momentsWithPhotos || []).filter(m => m && m.imageBase64);
  if (photos.length === 0) return null;

  const canvas = document.createElement('canvas');
  const W = 1200;
  const H = 960;
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');

  // Warm archival cream background
  ctx.fillStyle = '#F7F3EA';
  ctx.fillRect(0, 0, W, H);

  const loadedImgs = await Promise.all(photos.map(p => new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve({ img, meta: p });
    img.onerror = () => resolve(null);
    img.src = p.imageBase64;
  })));
  const valid = loadedImgs.filter(Boolean);
  if (valid.length === 0) return null;

  const drawCoverCell = (imgObj, x, y, w, h, badgeLabel) => {
    ctx.save();
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(x, y, w, h, 14) : ctx.rect(x, y, w, h);
    ctx.clip();

    const img = imgObj.img;
    const scale = Math.max(w / img.width, h / img.height);
    const sw = img.width * scale;
    const sh = img.height * scale;
    const sx = x + (w - sw) / 2;
    const sy = y + (h - sh) / 2;
    ctx.drawImage(img, sx, sy, sw, sh);

    // Subtle dark gradient at top-left for moment number badge
    if (badgeLabel) {
      ctx.fillStyle = 'rgba(15, 23, 42, 0.78)';
      ctx.fillRect(x + 12, y + 12, 96, 30);
      ctx.fillStyle = '#F59E0B';
      ctx.font = '800 14px Inter, sans-serif';
      ctx.fillText(badgeLabel, x + 22, y + 32);
    }
    ctx.restore();

    ctx.strokeStyle = '#E2D9C5';
    ctx.lineWidth = 4;
    ctx.strokeRect(x, y, w, h);
  };

  const pad = 18;
  const gap = 14;
  if (valid.length === 1) {
    drawCoverCell(valid[0], pad, pad, W - pad * 2, H - pad * 2, `MOMENT 0${valid[0].meta.index}`);
  } else if (valid.length === 2) {
    const cellW = (W - pad * 2 - gap) / 2;
    const cellH = H - pad * 2;
    drawCoverCell(valid[0], pad, pad, cellW, cellH, `MOMENT 0${valid[0].meta.index}`);
    drawCoverCell(valid[1], pad + cellW + gap, pad, cellW, cellH, `MOMENT 0${valid[1].meta.index}`);
  } else if (valid.length === 3) {
    const leftW = Math.round((W - pad * 2 - gap) * 0.52);
    const rightW = (W - pad * 2 - gap) - leftW;
    const rightH = (H - pad * 2 - gap) / 2;
    drawCoverCell(valid[0], pad, pad, leftW, H - pad * 2, `MOMENT 0${valid[0].meta.index}`);
    drawCoverCell(valid[1], pad + leftW + gap, pad, rightW, rightH, `MOMENT 0${valid[1].meta.index}`);
    drawCoverCell(valid[2], pad + leftW + gap, pad + rightH + gap, rightW, rightH, `MOMENT 0${valid[2].meta.index}`);
  } else {
    const cellW = (W - pad * 2 - gap) / 2;
    const cellH = (H - pad * 2 - gap) / 2;
    drawCoverCell(valid[0], pad, pad, cellW, cellH, `MOMENT 0${valid[0].meta.index}`);
    drawCoverCell(valid[1], pad + cellW + gap, pad, cellW, cellH, `MOMENT 0${valid[1].meta.index}`);
    drawCoverCell(valid[2], pad, pad + cellH + gap, cellW, cellH, `MOMENT 0${valid[2].meta.index}`);
    drawCoverCell(valid[3], pad + cellW + gap, pad + cellH + gap, cellW, cellH, `MOMENT 0${valid[3].meta.index}`);
  }

  return canvas.toDataURL('image/jpeg', 0.88);
}

function acceptPolishedTake() {
  const input = document.getElementById('creatorSlantTakeInput');
  const reviewCard = document.getElementById('slantPolishReviewCard');
  if (input && lastPolishedTake) {
    input.value = lastPolishedTake;
    if (creatorSelectedSource === 'inner_voice' && isDailyChronicleMode) {
      const blocks = String(lastPolishedTake).split(/\n\s*\n|(?:^|\s+)(?=(?:0?[1-3]\s*[·•.-]\s*)?Moment\s+0?[1-3]\b|0?[1-3]\s*[·•.-])/gi).map(b => b.trim()).filter(Boolean);
      if (blocks.length >= 2) {
        blocks.slice(0, 3).forEach((blk, idx) => {
          if (!dailyChronicleMoments[idx]) {
            dailyChronicleMoments[idx] = { id: Date.now() + idx, title: '', text: '', imageBase64: null, imageMimeType: 'image/jpeg' };
          }
          const mMatch = blk.match(/^(?:0?[1-9]\s*[·•.-]\s*)?Moment\s+\d+(?:\s*[·•.-]\s*([^:]{1,38}))?:\s*([\s\S]+)$/i);
          if (mMatch) {
            if (mMatch[1] && !/^moment\s*\d+$/i.test(mMatch[1].trim())) {
              dailyChronicleMoments[idx].title = mMatch[1].trim();
            }
            dailyChronicleMoments[idx].text = mMatch[2].trim();
          } else {
            dailyChronicleMoments[idx].text = blk.replace(/^(?:0?[1-9]\s*[·•.-]\s*)?(?:Moment\s+\d+\s*:?\s*)?/i, '').trim();
          }
        });
        renderDailyChronicleCards();
        syncChronicleMomentsToSlantInput();
      }
    }
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }
  if (reviewCard) {
    reviewCard.style.display = 'none';
  }
  if (typeof recordVisualConfidenceApproval === 'function') {
    recordVisualConfidenceApproval('polish_accept');
  }
  showTemporaryToast('✓ Polished take & visual selection applied to your slant!');
}

function rejectPolishedTake() {
  const reviewCard = document.getElementById('slantPolishReviewCard');
  if (reviewCard) {
    reviewCard.style.display = 'none';
  }
  showTemporaryToast('Original take kept.');
}

function toggleRefineCoreTake(val) {
  if (typeof val === 'boolean') {
    creatorRefineCoreTake = val;
  } else {
    creatorRefineCoreTake = !creatorRefineCoreTake;
  }

  const card = document.getElementById('slantRefineToggleCard');
  const sw = document.getElementById('refineCoreTakeSwitch');
  const icon = document.getElementById('slantRefineIcon');
  const title = document.getElementById('slantRefineTitle');
  const badge = document.getElementById('slantRefineBadge');
  const sub = document.getElementById('slantRefineSubtitle');

  if (sw) sw.checked = creatorRefineCoreTake;
  if (card) card.classList.toggle('refined', creatorRefineCoreTake);

  if (creatorRefineCoreTake) {
    if (icon) icon.textContent = '✨';
    if (title) title.textContent = 'Refine Poster 2 Take';
    if (badge) {
      badge.textContent = 'Refined';
      badge.className = 'slant-refine-badge';
    }
    if (sub) sub.textContent = 'Polishes your typed thoughts into a punchy 2-sentence quote for Poster 2.';
  } else {
    if (icon) icon.textContent = '❝';
    if (title) title.textContent = 'Use Poster 2 Take As-Is';
    if (badge) {
      badge.textContent = 'Verbatim';
      badge.className = 'slant-refine-badge verbatim';
    }
    if (sub) sub.textContent = 'Keeps your exact typed words verbatim on Poster 2 without rephrasing.';
  }
  if (typeof evaluateSmartRegenScopeAutoSwitch === 'function') {
    evaluateSmartRegenScopeAutoSwitch();
  }
}

let creatorVocabularyStyle = 'casual'; // Internal default: Casual with simple, easily understood words

function setVocabularyStyle(style) {
  creatorVocabularyStyle = style || 'casual';
  const badge = document.getElementById('slantVocabBadge');
  const sub = document.getElementById('slantVocabSubtitle');

  document.querySelectorAll('.slant-vocab-pill').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.vocab === style);
  });

  if (style === 'conversational' || style === 'casual') {
    if (badge) badge.textContent = '💬 Casual';
    if (sub) sub.textContent = 'Natural everyday English. Clean, grounded, and universally easy to read.';
  } else if (style === 'analytical') {
    if (badge) badge.textContent = '🏛 Analytical';
    if (sub) sub.textContent = 'Formal editorial broadsheet vocabulary for deep policy or structural critique.';
  } else {
    // punchy
    if (badge) badge.textContent = '⚡ Punchy';
    if (sub) sub.textContent = 'Emotional, vivid & clear. Strong verbs, zero academic jargon. Reads effortlessly.';
  }
  if (typeof evaluateSmartRegenScopeAutoSwitch === 'function') {
    evaluateSmartRegenScopeAutoSwitch();
  }
}

let creatorPerspectiveMode = 'source'; // 'curator' | 'hybrid' | 'source' (Default: 'source')

function setPerspectiveMode(mode, fromUserClick = false) {
  if (mode !== 'curator' && mode !== 'source' && mode !== 'hybrid') {
    mode = 'source';
  }
  const prevMode = creatorPerspectiveMode;
  creatorPerspectiveMode = mode;
  if (fromUserClick && typeof evaluateSmartRegenScopeAutoSwitch === 'function') {
    setTimeout(() => evaluateSmartRegenScopeAutoSwitch(), 0);
  }

  document.querySelectorAll('.slant-perspective-pill').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.perspective === mode);
  });

  const hasPhoto = Boolean(creatorReferenceImageBase64 || currentScrapedArticle?.imageBase64 || currentScrapedArticle?.imageUrl);

  let iconText = '📰';
  let badgeText = '📰 Source Grounded';
  let subText = 'Controls Poster 1 Artwork & Cues: Artwork stays 100% faithful to the authentic news event, subjects, and photo.';

  if (mode === 'curator') {
    iconText = '⚡';
    badgeText = '⚡ Curator Angle';
    subText = 'Controls Poster 1 Artwork & Cues: Artwork reflects your conceptual metaphor and critique.';
  } else if (mode === 'hybrid') {
    iconText = '⚖️';
    badgeText = hasPhoto ? '⚖️ Hybrid Likeness' : '⚖️ Hybrid Blend';
    subText = hasPhoto
      ? 'Controls Poster 1 Artwork & Cues: Blends your personal take with the facial structure, setting, and people in your photo (Zero Digital Footprint).'
      : 'Controls Poster 1 Artwork & Cues: Blends the real-world news subject with your visual metaphor.';
  }

  document.querySelectorAll('#slantPerspectiveIcon, .slant-perspective-icon').forEach(el => { el.textContent = iconText; });
  document.querySelectorAll('#slantPerspectiveBadge, .slant-perspective-badge-dyn').forEach(el => { el.textContent = badgeText; });
  document.querySelectorAll('#slantPerspectiveSubtitle, .slant-perspective-sub-dyn').forEach(el => { el.textContent = subText; });

  // Update Equalizer Focus UI
  const eqSrc = document.getElementById('eqFocusSource');
  const eqHyb = document.getElementById('eqFocusHybrid');
  const eqCur = document.getElementById('eqFocusCurator');
  if (eqSrc) eqSrc.classList.toggle('active', mode === 'source');
  if (eqHyb) eqHyb.classList.toggle('active', mode === 'hybrid');
  if (eqCur) eqCur.classList.toggle('active', mode === 'curator');

  const eqExpl = document.getElementById('equalizerFocusExplainer');
  if (eqExpl) {
    if (mode === 'source') {
      eqExpl.textContent = 'Physically anchored in authentic news subjects, real press setting, and source photograph.';
    } else if (mode === 'curator') {
      eqExpl.textContent = 'Sharp conceptual metaphor and critical thesis driven purely by your slant take.';
    } else {
      eqExpl.textContent = hasPhoto
        ? 'Blends your personal angle with the facial likeness and setting of your photo.'
        : 'Blends the real-world news subject with your personal visual metaphor.';
    }
  }

  updateReferencePhotoUI();
  updateEqualizerSummary();

  // If user clicked a different Visual Focus while inside Stage 2 and cues exist, auto-refresh cues to match
  const isClick = Boolean(fromUserClick);
  const s2 = document.getElementById('creatorStep2');
  const isStage2Visible = s2 && s2.style.display !== 'none';
  if (isClick && mode !== prevMode && isStage2Visible && creatorCuePills.length > 0) {
    showTemporaryToast(`🔄 Visual focus set to ${badgeText}: Updating visual cues...`);
    triggerCueSuggest();
  }
}

